def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    tile_counts = sorted(set(sum(tile) for tile in tiles))
    remaining_area = h * w

    for count in tile_counts:
        if count > remaining_area:
            return False
        if remaining_area % count == 0:
            if remaining_area // count <= n:
                return True
            n -= remaining_area // count - 1
            remaining_area = remaining_area % count
    return False

