def kth_smallest_amount(coins: List[int], k: int) -> int:
    def counts(c, coins):
        ret = 0
        for coin in coins:
            ret += c // coin
        return ret

    if k > (1 << len(coins)) * counts(k, coins):
        return -1

    pq = []
    for coin in coins:
        if coin <= k:
            heapify(pq)
            while len(pq) > counts(k, coins) - (k - 1):
                heapreplace(pq, -pop(pq))
            heappushpop(pq, -coin)
        else:
            heappushpop(pq, -coin * (k // coin + 1))
        k %= counts(k, coins)
    return -pop(pq)

