from math import comb

def count_special_permutations(A: int, B: int, M: int) -> int:
    def count_is(k: int, A: int) -> int:
        return comb(k - 1, A - 1) % M

    perm_count = 0
    for i in range(A + 1):
        for j in range(B + 1):
            length = A + B - i - j
            if length <= A:
                perm_count += comb(length + A - 1, A - 1) * comb(A - 1, i) * (1 if i == 0 else comb(length + j, j))
                perm_count %= M

    for k in range(A, A + B):
        perm_count -= count_is(k, A) * count_is(k, B)
        perm_count %= M
    return perm_count

