    for i in range(1, n+1):
        for j in range(m+1):
            for p in range(k+1):
                dp[i][j][p] = dp[i-1][j][p] * (m-j) % mod
                if p > 0:
                    dp[i][j][p] += dp[i-1][j-1][p-1] * (m-j+1) % mod
                dp[i][j][p] %= mod

