def find_largest_400_number(a: int) -> int:
    def is_400_number(n: int) -> bool:
        primes = pow(n, 0.5) + 1
        sieve = [True] * primes
        sieve[0] = sieve[1] = False
        for i in range(2, primes):
            if sieve[i]:
                for j in range(i * i, primes, i):
                    sieve[j] = False
        prs = [i for i, prime in enumerate(sieve) if prime]
        factors = set()
        for pr in prs:
            while n % pr == 0:
                factors.add(pr)
                n //= pr
            if n < pr:
                break
        return len(factors) == 2 and all(n % p == 0 for p in factors)

    max_n = 0
    for n in range(min(a, 10**12), 0, -1):
        if is_400_number(n):
            max_n = n
            break
    return max_n


