def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    def is_semi_palindrome(s: str) -> bool:
        n = len(s)
        counts = [0] * 26
        for c in s:
            counts[ord(c) - ord('a')] += 1
        odd_count = sum(1 for count in counts if count % 2)
        return odd_count <= 1 and any(n % i == 0 for i in range(2, n + 1))

    def min_changes(s: str, d: int) -> int:
        n = len(s)
        changes = 0
        for i in range(0, n, d):
            substring = s[i:i + d]
            for j in range(d // 2):
                if substring[j] != substring[d - j - 1]:
                    changes += 1
        return changes

    partitions = [(d, i) for d in range(1, len(s) + 1) for i in range(0, len(s), d)]
    partitions.sort(key=lambda x: x[1])
    dp = [float('inf')] * (k + 1)
    dp[0] = 0
    for d, i in partitions:
        for j in range(k, 0, -1):
            dp[j] = min(dp[j], dp[j - 1] + min_changes(s, d))
    return dp[k]

