def min_time_to_reduce_sum(nums1: List[int], nums2: List[int], x: int) -> int:
    total_sum = sum(nums1) + sum(nums2)
    if total_sum <= x:
        return 0
    time_needed = 0
    for i in range(len(nums1)):
        time_needed += 1
        nums1[i] += nums2[i]
        while nums1[i] >= x:
            nums1[i] -= x
            time_needed += 1
    return time_needed

def max_partitions_with_one_change(s: str, k: int) -> int:
    from collections import defaultdict

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a // gcd(a, b) * b

    def partitions(s, k):
        partitions = []
        counts = defaultdict(int)
        start = 0
        max_partitions = 0

        for end in range(len(s)):
            counts[s[end]] += 1
            while len(counts) > k:
                counts[s[start]] -= 1
                if counts[s[start]] == 0:
                    del counts[s[start]]
                start += 1
            if end - start + 1 <= k:
                partitions.append(end - start + 1)
        return partitions

    orig_partitions = partitions(s, k)
    max_partitions = max(orig_partitions)

    for i in range(len(s)):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            new_s = s[:i] + c + s[i+1:]
            new_partitions = partitions(new_s, k)
            max_partitions = max(max_partitions, max(new_partitions))

    return max_partitions

