MOD = 998244353

def power(x: int, y: int) -> int:
    result = 1
    while y > 0:
        if y & 1:
            result = (result * x) % MOD
        x = (x * x) % MOD
        y >>= 1
    return result

def modInverse(x: int) -> int:
    return power(x, MOD - 2) if power(x, MOD - 2) else None

def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
    if n == 0 or any(f <= 1 for f in dice_faces):
        return 0

    target = 10
    max_sum = sum(dice_faces)
    if max_sum < target:
        return 0

    dp = [[0 for _ in range(max_sum + 1)] for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(max_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= dice_faces[i - 1]:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - dice_faces[i - 1]]) % MOD

    subset_count = (dp[n][target] - dp[n][target - 1]) % MOD
    total_combinations = power(reduce(mul, dice_faces), n)

    return (subset_count * modInverse(total_combinations)) % MOD

