def min_cost_to_achieve_goal(n: int, k: int, p: int, plans: List[Tuple[int, List[int]]]) -> int:
    from typing import List, Tuple
    from sortedcontainers import SortedSet
    from collections import defaultdict

    def get_param_set(plan: Tuple[int, List[int]]) -> SortedSet[int]:
        cost, increases = plan
        return SortedSet(increase + 1 for increase in increases)

    def get_cost(param_set: SortedSet[int], target: int) -> int:
        return max(0, target - param_set.bisect_left(target) + 1)

    def min_cost(target: int, plans: List[Tuple[int, List[int]]]) -> int:
        dp = defaultdict(lambda: float('inf'))
        dp[0] = 0
        for cost, param_set in plans:
            new_dp = dp.copy()
            for target in dp:
                new_target = max(target, param_set.bisect_left(target) + 1)
                new_dp[new_target] = min(new_dp[new_target], dp[target] + cost)
            dp = new_dp
        return dp[target] if dp[target] != float('inf') else -1

    return min_cost(p * k, plans)

