from typing import List

def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    from collections import defaultdict
    from itertools import permutations

    def is_equal(A_row: List[int], B_row: List[int]) -> bool:
        return sorted(A_row) == sorted(B_row)

    def is_matchable(A: List[List[int]], B: List[List[int]]) -> bool:
        if len(A) != len(B) or any(len(row_A) != len(row_B) for row_A, row_B in zip(A, B)):
            return False
        return all(is_equal(row_A, row_B) for row_A, row_B in zip(A, B))

    def generate_swaps(H: int, W: int) -> List[List[int]]:
        swaps = list(permutations(range(1, H + 1), r=2)) + list(permutations(range(1, W + 1), r=2))
        return [[x, y] for x, y in swaps if x < H and y < W]

    operations = 0
    for swap in generate_swaps(H, W):
        A_copy = [row.copy() for row in A]
        B_copy = [row.copy() for row in B]
        for i in range(swap[0] - 1, -1, -1):  # swap rows
            A_copy[i], A_copy[i + 1] = A_copy[i + 1], A_copy[i]
            B_copy[i], B_copy[i + 1] = B_copy[i + 1], B_copy[i]
        for i in range(swap[1] - 1, -1, -1):  # swap columns
            for j in range(H):  # swap columns for each row
                A_copy[j][i], A_copy[j][i + 1] = A_copy[j][i + 1], A_copy[j][i]
                B_copy[j][i], B_copy[j][i + 1] = B_copy[j][i + 1], B_copy[j][i]
        if is_matchable(A_copy, B_copy):
            return operations
        operations += 1
    return None

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    def count_points(color: int) -> int:
        return sum(point for row in grid for point in row if point == color)

    def check_consecutive_possible(color: int, direction: List[List[int]]) -> bool:
        for i in range(len(grid)):
            if all(cell == color for cell in direction[i]):
                return True
        return False

    Takahashi_points = count_points(-1)  # -1 is red
    Aoki_points = count_points(1)   # 1 is blue

    # Check for 3 consecutive cells for each player
    for direction in [[[grid[i][0], grid[i][1], grid[i][2]] for i in range(3)],
                      [[grid[0][i] for i in range(3)], [grid[1][i] for i in range(3)], [grid[2][i] for i in range(3)]],
                      [[grid[i][i] for i in range(3)], [grid[i][2 - i] for i in range(3)]]]:
        if check_consecutive_possible(color, direction):
            return 'Takahashi' if color == -1 else 'Aoki'

    return 'Takahashi' if Takahashi_points > Aoki_points else 'Aoki'

