def count_paths(N, M, K, extra_edges):
    MOD = 998244353
    dp = [[[0] * (K + 1) for _ in range(N)] for _ in range(2)]
    dp[0][0][0] = 1
    for _ in range(2):
        for i in range(N):
            for j in range(K + 1):
                if j - 1 >= 0:
                    dp[1 - _ % 2][i][j] = dp[1 - _ % 2][(i + 1) % N][j - 1]
                if _ < 2 or (i, j) not in [(N - 1, 0), (0, 0)]:
                    for x, y in extra_edges:
                        if i == x: dp[1 - _ % 2][y][j + 1] += dp[1 - _ % 2][i][j]
                        if i == y: dp[1 - _ % 2][x][j + 1] += dp[1 - _ % 2][i][j]
                    dp[1 - _ % 2][i][j] %= MOD
    return dp[1][0][K]

