def max_score(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]
    dp_unique = [set() for _ in range(rows)]
    max_score = 0

    for i in range(rows):
        dp[i][0] = grid[i][0] if not grid[i][0] in dp_unique[i] else 0
        dp_unique[i].add(grid[i][0])
        max_score = max(max_score, dp[i][0])

    for j in range(1, cols):
        max_prev_score = max(dp[i][k] for i in range(rows) for k in range(j))
        max_score_with_new_col = 0

        for i in range(rows):
            for k in range(j):
                dp[i][j] = max_prev_score
                if grid[i][j] in dp_unique[i]:
                    dp[i][j] = max(dp[i][j], dp[i][k] + grid[i][j])
                else:
                    dp_unique[i].add(grid[i][j])
                max_score_with_new_col = max(max_score_with_new_col, dp[i][j])

        max_score = max(max_score, max_score_with_new_col)
    return max_score

def max_subsequence_value(nums: List[int], k: int) -> int:
    n = len(nums)
    if n < 2 * k:
        return 0

    max_val = 0
    for left in range(n - 2 * k + 1):
        right = left + 2 * k
        seq1 = 0
        seq2 = 0

        for i in range(left, left + k):
            seq1 |= nums[i]
        for i in range(left + k, right):
            seq2 |= nums[i]

        max_val = max(max_val, seq1 ^ seq2)

    return max_val

def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    from typing import List
    import heapq
    orders = [(abs(order_days[i] - day), day, i) for i, day in enumerate(order_days)]
    heapq.heapify(orders)
    dissatisfaction = 0
    prev_day = 0
    shipments = []
    while orders or shipments:
        if not shipments or heapq.heappop(orders)[1] >= prev_day + x:
            shipment_days = []
            for _ in range(k):
                if not orders:
                    break
                _, day, _ = heapq.heappop(orders)
                if day <= prev_day + x:
                    heapq.heappush(orders, (abs(day - prev_day), day, _))
                else:
                    shipment_days.append(day)
            if shipment_days:
                prev_day = max(shipment_days)
                dissatisfaction += sum(d - (day + x if day in shipment_days else day) for day, _, _ in orders)
            shipments.append(shipment_days)
    return dissatisfaction

