def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    A, P, B, Q = zip(*machines)
    dp = [0] * (x + 1)
    for a, p, b, q in sorted(zip(A, P, B, Q), reverse=True):
        for c in range(x, p - 1, -1):
            dp[c] = max(dp[c], min(dp[c - p], a))
            if c >= q:
                dp[c] = max(dp[c], min(dp[c - q], b))
    return min(dp)

def count_paths(H, W, K, grid):
    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    count = [[0 for _ in range(W)] for _ in range(H)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, moves_left):
        if moves_left == 0:
            return 1
        if count[x][y] > 0:
            return count[x][y]

        count[x][y] = 0
        res = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and grid[nx][ny] == '.':
                res += dfs(nx, ny, moves_left - 1)
        count[x][y] = res
        return res

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                res = dfs(i, j, K - 1)
                return res

    return 0

