def max_eleven_twentytwo_subsequence(s: str, l: int, r: int) -> int:
    max_length = 0
    for i in range(l-1, r):
        if s[i] == '/':
            left_ones = 0
            right_twos = 0
            j = i - 1
            while j >= l-1 and s[j] == '1':
                left_ones += 1
                j -= 1
            j = i + 1
            while j <= r and s[j] == '2':
                right_twos += 1
                j += 1
            if left_ones + right_twos + 1 == (left_ones + right_twos + 1) // 2 * 2 and left_ones + right_twos + 1 > max_length:
                max_length = left_ones + right_twos + 1
    return max_length

