        count[a[right]] += 1
        while count[a[left]] % 2 != 0:
            count[a[left]] -= 1
            left += 1
        if (right - left + 1) % 2 == 0 and all(val % 2 == 0 for val in count.values()):
            max_length = max(max_length, (right - left + 1))
    return max_length

