def min_longest_substring(s: str, numOps: int) -> int:
    if not s or numOps < 0 or numOps > len(s):
        return 0
    if numOps == 0:
        return max(len(list(group)) for group in itertools.groupby(s))

    left = 0
    max_length = 0
    zero_count = 0
    one_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zero_count += 1
        else:
            one_count += 1

        while (zero_count > numOps or one_count > numOps) and left <= right:
            if s[left] == '0':
                zero_count -= 1
            else:
                one_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

def count_balanced_graphs(n: int, p: int) -> list[int]:
