    from itertools import combinations
    from functools import lru_cache

    def catalan(m):
        return comb(2*m, m) // (m + 1)

    def count_even_odd_dist(n, m):
        cnt = 0
        for edges in combinations(range(n), m):
            adj_list = {i: [] for i in range(n)}
            for u, v in edges:
                adj_list[u].append(v)
                adj_list[v].append(u)
            visited = [False] * n
            q = [(0, 0)]  # time, distance
            while q:
                time, dist = q.pop(0)
                if visited[dist]: continue
                visited[dist] = True
                cnt += (dist % 2 == 0)  # even distance
                for nei in adj_list[dist]:
                    if not visited[nei]:
                        q.append((time + 1, nei))
        return cnt % p

    return [count_even_odd_dist(n, M) for M in range(n-1, n*(n-1) // 2 + 1, n-1)]

