def min_swaps_to_group_ones(n: int, s: str) -> int:
    ones = [i for i, char in enumerate(s) if char == '1']
    length = len(ones)

    if length == 0 or length == n:
        return 0

    start, end = ones[0], ones[-1]
    swaps = start + n - 1 - end

    for i in range(1, length):
        swaps += (ones[i] - ones[i - 1]) * (length - i)

    return swaps // 2

