def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    n = len(nums)
    dp = [[-1] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    even_sum = [0] * (n + 1)
    odd_sum = [0] * (n + 1)
    product = [1] * (n + 1)

    for i in range(1, n + 1):
        even_sum[i] = even_sum[i - 1] + (nums[i - 1] if i % 2 == 0 else 0)
        odd_sum[i] = odd_sum[i - 1] + (nums[i - 1] if i % 2 != 0 else 0)
        product[i] = product[i - 1] * nums[i - 1] if nums[i - 1] <= limit // product[i - 1] else -1

    for i in range(1, n + 1):
        for j in range(k + 1):
            if j <= even_sum[i] - k:
                dp[i][j] = max(dp[i - 1][j], odd_sum[i] - j if odd_sum[i] - j >= 0 else -1, even_sum[i] - k - j if even_sum[i] - k - j >= 0 else -1) * product[i]
            else:
                dp[i][j] = -1

    return dp[n][k]

