def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    if n < 3 or n > 5:
        return None

    # Check if R and C have valid combinations of A, B, and C
    r_count = {char: r.count(char) for char in 'ABC'}
    c_count = {char: c.count(char) for char in 'ABC'}
    if r_count != {char: 1 for char in 'ABC'} or c_count != {char: 1 for char in 'ABC'}:
        return None

    # Generate all possible permutations of (A, B, C)
    permutations = list(itertools.permutations('ABC'))
    for perm in permutations:
        grid = []
        # Create the grid with initial row and column constraints
        for i in range(n):
            row = ''
            col = ''
            row += perm[i % 3]
            col += perm[(i + 1) % 3]
            grid.append(f'{row}{col}')

        # Check row and column constraints
        if (sorted(row) == list('ABC') for row in grid) and (sum(sorted(cell) == list('ABC') for cell in zip(*grid)) == n):
            return grid

    return None

