def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    def can_place_tile(t_a: int, t_b: int, grid: List[List[bool]]) -> bool:
        for i in range(h - t_a + 1):
            for j in range(w - t_b + 1):
                if grid[i][j] and all(grid[i+x:i+x+t_a][j:j+t_b] for x in range(t_a)):
                    return True
        return False

    grid = [[False] * w for _ in range(h)]
    for _ in range(n):
        if can_place_tile(max(t[0] for t in tiles), max(t[1] for t in tiles), grid):
            continue
        for t_a, t_b in tiles:
            if can_place_tile(t_a, t_b, grid):
                break
        else:
            return False
    return all(grid[0][_] for _ in range(w)) and all(grid[-1][_] for _ in range(w)) and
           all(_[0] for _ in grid) and all(_[-1] for _ in grid[::-1])

