def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    # Convert input coordinates to tile indices
    def to_indices(x: int, y: int, K: int) -> (int, int):
        return (x // K, y // K)

    S_i, S_j = to_indices(S_x + 0.5, S_y + 0.5, K)
    T_i, T_j = to_indices(T_x + 0.5, T_y + 0.5, K)

    # Calculate distance between tiles, considering board wrap-around
    dx = abs(T_i - S_i) % (2 * K)
    dy = abs(T_j - S_j) % (2 * K)

    # Maximum distance in case moving diagonally
    max_dist = max(dx, dy) + (2 * K - max(dx, dy))

    # Calculate minimum moves, then add any diagonal moves
    min_moves = max_dist
    if dx == max_dist and dy == max_dist:
        min_moves += 2
    elif dx > dy:
        min_moves += dx - dy
    else:
        min_moves += dy - dx

    return min_moves

