        return None
    m = n // 3
    lo, hi = 1, m
    while lo <= hi:
        mid = (lo + hi) // 2
        cube = mid**3
        if cube == m:
            return (mid + 1, mid)
        elif cube < m:
            lo = mid + 1
        else:
            hi = mid - 1
    return None

def find_largest_400_number(a: int) -> int:
    def count_prime_factors(n: int) -> list:
        i = 2
        prime_factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                prime_factors.append(i)
        if n > 1:
            prime_factors.append(n)
        return prime_factors

    def is_400_number(n: int) -> bool:
        factors = count_prime_factors(n)
        if len(factors) != 2:
            return False
        for factor in factors:
            if n % (factor * factor) != 0:
                return False
        return True

    largest_400_number = 0
    for i in range(a, 0, -1):
        if is_400_number(i):
            largest_400_number = i
            break
    return largest_400_number

