def min_cost_to_achieve_goal(n, k, p, plans):
    from heapq import heappop, heappush
    from typing import List, Tuple

    def is_valid(current, target):
        return all(current[i] >= target[i] for i in range(len(target)))

    min_heap = [(plan[0], plan[1], i) for i, plan in enumerate(plans)]
    heapq.heapify(min_heap)
    visited = [False] * n

    while min_heap:
        cost, increases, plan_idx = heappop(min_heap)
        if visited[plan_idx]: continue
        visited[plan_idx] = True

        current = [target[i] - increases[i] for i in range(k)]

        if is_valid(current, [p] * k):
            return cost

        for i, increase in enumerate(increases):
            new_current = current.copy()
            new_current[i] += increase
            if not is_valid(new_current, [p] * k):
                heappush(min_heap, (cost + plans[plan_idx][0], increases, plan_idx))

    return -1

