def kruskal(n, edges, k):
    edges.sort(key=lambda x: x[2])
    parent = [i for i in range(n)]
    rank = [0] * n
    mst_edges = []
    total_cost = 0
    for edge in edges:
        u, v, w = edge
        root_u = find(parent, u)
        root_v = find(parent, v)
        if root_u != root_v:
            mst_edges.append(edge)
            parent[root_u] = root_v
            total_cost += w % k
            if total_cost >= k:
                total_cost %= k
    return total_cost

