def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    """
    Given two grids A and B of dimensions H x W, determine if it's possible to transform
    grid A into grid B using only adjacent row swaps and adjacent column swaps.

    Operations allowed:
    - Swap row i with row i+1 (for 1 <= i < H)
    - Swap column i with column i+1 (for 1 <= i < W)

    If transformation is possible, return the minimum number of operations required.
    If transformation is impossible, return None.

    Args:
        H: Number of rows (2 <= H <= 5)
        W: Number of columns (2 <= W <= 5)
        A: Initial grid as a list of lists
        B: Target grid as a list of lists

    Returns:
        Minimum number of operations if possible, None otherwise
    """

    def is_equal(grid1: List[List[int]], grid2: List[List[int]]) -> bool:
        return all(a == b for a, b in zip(grid1, grid2))

    def min_ops_to_match(grid1: List[List[int]], grid2: List[List[int]], return_path: bool = False) -> int:
        if is_equal(grid1, grid2):
            return 0 if return_path else None

        min_ops = float('inf')
        all_ops = []

        for i in range(1, H):
            for j in range(1, W):
                for k in range(min(i, H - i), 0, -1):
                    temp = [row[:j] + row[j+1:] for row in grid1]
                    temp = [row[:k] + row[k+1:] + row[k:k+1] for row in temp]
                    for l in range(min(j, W - j), 0, -1):
                        temp = [row[:l] + row[l+1:] for row in temp]
                        if is_equal(temp, grid2):
                            ops = sum(1 for t in temp if is_equal(t, grid1))
                            min_ops = min(min_ops, ops)
                            if return_path and ops == min_ops:
                                all_ops.append((i, j, k, l))

        return min_ops if return_path else None

    if H % 2 == 0 or W % 2 == 0:
        return None

    path = min_ops_to_match(A, B, return_path=True)
    if path:
        ops = sum(1 for i, j, k, l in path for _ in range(k) for _ in range(l))
        return ops
    else:
        return None

