def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    lcm_map = [[None] * (n + 1) for _ in range(n + 1)]
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for j in range(n - 1, -1, -1):
        for i in range(j + 1, n + 1):
            dif = a[j] - a[i]
            lcm = (dif * (i - j)) // gcd(dif, i - j)
