def min_team_switches(people):
    team_strengths = {1: 0, 2: 0, 3: 0}
    total_people = len(people)
    people_switched = 0
    total_strength = sum(strength for _, strength in people)
    target_strength = total_strength // 3
    if total_strength % 3 != 0:
        return -1
    for team, strength in people:
        team_strengths[team] += strength
    while not are_teams_equal(team_strengths):
        for team in range(1, 4):
            min_team = team
            max_strength = -1
            for other_team, strength in team_strengths.items():
                if abs(strength - target_strength) < abs(max_strength - target_strength):
                    max_strength = strength
                    min_team = other_team
            person_to_switch = get_least_strong_person(people, min_team)
            if person_to_switch is None:
                return -1
            people_switched += 1
            people[people.index(person_to_switch)] = (max_strength, person_to_switch[1])
            team_strengths[person_to_switch[0]] -= person_to_switch[1]
            team_strengths[max_strength] += person_to_switch[1]
        if team_strengths[1] > target_strength:
            min_team = 1
        elif team_strengths[2] > target_strength:
            min_team = 2
        else:
            min_team = 3
        person_to_switch = get_least_strong_person(people, min_team)
        if person_to_switch is None:
            return -1
        people_switched += 1
        people[people.index(person_to_switch)] = (target_strength, person_to_switch[1])
    return people_switched

