def get_least_strong_person(people, min_team):
    least_strong = max_strength = -1
    for person in people:
        if person[0] == min_team and (max_strength is -1 or person[1] < max_strength):
            max_strength = person[1]
            least_strong = person
    return least_strong

def count_paths(H, W, K, grid):
    from typing import List
    from collections import defaultdict

    # Directions for adjacent cells
    dx, dy = [0, 1, 0, -1], [1, 0, -1, 0]

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    def valid(x, y):
        return grid[x][y] == '.'

    # Build adjacency list
    adj_list = defaultdict(list)
    for r in range(H):
        for c in range(W):
            if valid(r, c):
                for d in range(4):
                    nr, nc = r + dx[d], c + dy[d]
                    if in_bounds(nr, nc) and valid(nr, nc):
                        adj_list[r * W + c].append(nr * W + nc)

    def dfs(start, end, paths):
        paths[start] += 1
        if start == end:
            return paths[start]
        for neighbor in adj_list[start]:
            dfs(neighbor, end, paths)
        paths[start] = 0

    # Calculate number of paths
    path_count = 0
    for start in range(H * W):
        if valid(start // W, start % W):
            path_count += dfs(start, end := start + K, paths=defaultdict(int))
    return path_count

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353
    DP = [[[0] * 4 for _ in range(W)] for _ in range(H)]
    RESULT = 0

    def count_ways(r: int, c: int, prev_digit: int) -> None:
        nonlocal RESULT
        if r == H: return
        if c == W: count_ways(r + 1, 0, 0) if r < H - 1 else RESULT += 1; return

        if c > 0 and grid[r][c - 1] == grid[r][c] or grid[r][c - 1] == '?' and grid[r][c] != '?' and grid[r][c - 1] != prev_digit:
            count_ways(r, c + 1, prev_digit)
            return

        digit = grid[r][c] if grid[r][c] != '?' else prev_digit
        DP[r][c][digit] = (DP[r][c][digit] + 1) % MOD
        count_ways(r, c + 1, digit)

    for c in range(W):
        if grid[0][c] == '?':
            for d in range(1, 4):
                count_ways(0, c + 1, d)
        else:
            break

    return RESULT % MOD

