def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    adj = defaultdict(list)

    # Populate adjacency list and union-find data structures
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
        union(parent, rank, u, v)

    # Initialize dp table and result
    dp = [[0] * (1 << n) for _ in range(n + 1)]
    result = 0

    # Helper function to get maximum weight edge for a subset of vertices
    def get_max_weight(subset):
        max_weight = 0
        for v, w in adj[subset]:
            max_weight = max(max_weight, w)
        return max_weight

    # Helper function to update dp table
    def update_dp(u, subset):
        for i in range(1, (1 << n) - 1):
            if (1 << u) & i:
                curr_max_weight = get_max_weight(subset + (1 << u))
                dp[u][i] = min(dp[u][i], dp[u][i - (1 << u)] + curr_max_weight)
                curr_max_weight = get_max_weight(subset - (1 << u) - (1 << find(parent, u)))
                dp[u][i] = min(dp[u][i], dp[u][i - (1 << u)] + curr_max_weight)

    # Fill dp table and update result
    for u in range(1, n + 1):
        update_dp(u, 0)
        result += dp[u][(1 << n) - 1]

    # Permutate b to minimize the total weight
    b_indices = sorted(range(len(b)), key=lambda x: dp[b[x]][(1 << n) - 1])
    for i in b_indices:
        result += get_max_weight(set([a[i]] + set(b[:i]) + set(b[i+1:])))

    return result

