        count = 0
        for v in graph[u]:
            if v != prev:
                if len(graph[v]) == 1:
                    count += 1
                else:
                    dfs(v, u, graph)
        return count

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    central_vertex = 1
    for u in range(1, n + 1):
        if len(graph[u]) > 2:
            central_vertex = u
            break

    if len(graph[central_vertex]) < 2:
        return n - 1

    leaves = sum(1 for v in graph[central_vertex] if len(graph[v]) == 1)
    return n - leaves - 1

def can_transform(k: int, s: str, t: str) -> bool:
    len_s, len_t = len(s), len(t)
    diff = abs(len_s - len_t)

    # If the length difference is too large and k is not enough, return False
    if diff > k:
        return False

    # If the length difference is zero, check mismatches
    if len_s == len_t:
        return sum(1 for x, y in zip(s, t) if x != y) <= k

    # If the source string is longer, check insertions and replacements
    if len_s > len_t:
        return can_transform_longer(k, s, t, insert=True)

    # If the target string is longer, check deletions and replacements
    return can_transform_longer(k, t, s, insert=False)

# Helper function to handle longer string
def can_transform_longer(k: int, longer: str, shorter: str, insert: bool) -> bool:
    shorter_index = 0
    k_used = 0

    for char in longer:
        if shorter_index < len(shorter) and char == shorter[shorter_index]:
            shorter_index += 1
        else:
            if insert:
                # Use replace operation
                if k_used < k: k_used += 1
                else:
                    return False
            else:
                # Use delete operation
                if k_used < k: k_used += 1
                else:
                    return False

    return k_used <= k

