def count_subsequence_pairs(nums: List[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7
    ans = 0
    dp = [[{} for _ in range(n)] for _ in range(n)]

    # Precompute gcd and store each number as an independent subsequence
    for i in range(n):
        dp[i][i] = {nums[i]: 1}
        for j in range(i+1, n):
            g = gcd(nums[i], nums[j])
            dp[i][j] = dp[i][j-1].copy()
            if g in dp[i][j-1]:
                dp[i][j-1][g] += 1
            else:
                dp[i][j-1][g] = 1
            dp[i][j][g] = dp[i][j-1][g] + 1

    # Calculate the number of valid subsequence pairs
    for i in range(n):
        for j in range(i+1, n):
            for g1 in dp[i][j]:
                for g2 in dp[i][n-1]:
                    if g1 != g2:
                        ans += dp[i][j][g1] * (dp[j][n-1][g2] if j != n-1 else 1)
                        ans %= MOD
                    else:
                        ans += dp[i][j][g1] * ((dp[j][n-1][g2] + 1) if j != n-1 else dp[j][n-1][g2])
                        ans %= MOD

    return ans

def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    great_jumps = [x for x in range(a, b + 1) if x <= n]
    jump_matrix = [[False] * (n + 1) for _ in range(len(great_jumps) + 1)]
    jump_matrix[0][1] = True

    for i in range(1, len(jump_matrix)):
        for j in range(1, n + 1):
            if jump_matrix[i - 1][j]:
                for step in great_jumps:
                    next_square = j + step
                    if next_square > n or next_square in [interval[0] for interval in bad_intervals] or any(interval[0] <= next_square <= interval[1] for interval in bad_intervals):
                        continue
                    if not jump_matrix[i][next_square]:
                        jump_matrix[i][next_square] = True

    return jump_matrix[-1][-1]

