MOD = 998244353

def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    dp = [[defaultdict(int) for _ in range(n+1)] for _ in range(m+1)]
    res = [0] * (n+1)
    dp[0][0][0] = 1

    for i in range(m+1):
        for j in range(n+1):
            if i:
                for l in range(j+1):
                    dp[i][j][l] += dp[i-1][j][l] % MOD
                    dp[i][j][l] += dp[i-1][j-1][l] % MOD

                if l <= j-1:
                    dp[i][j][l] -= dp[i-1][j-1][l-1] % MOD

            else:
                for l in range(j+1):
                    dp[i][j][l] += 1

    for j in range(n+1):
        for l in range(j+1):
            res[j] = (res[j] + dp[m][j][l] * (m-l) % MOD) % MOD

    return res

