    MOD = 998244353
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = (prefix_sums[i] + a[i]) % MOD
    result = 0
    for l in range(n):
        for r in range(l, n):
            power = pow(prefix_sums[r + 1] - prefix_sums[l], k, MOD)
