def count_paths(W, H, L, R, D, U):
    MOD = 998244353
    dp = [[0] * (W + 1) for _ in range(H + 1)]
    for x in range(L, R + 1):
        dp[D - 1][x] = 1
        dp[U][x] = 1
    for y in range(D, U + 1):
        dp[y][L - 1] = 1
        dp[y][R] = 1
    for y in range(D, U + 1):
        for x in range(L, R + 1):
            if (x < L or x > R or y < D or y > U):
                dp[y][x] = 0
            else:
                dp[y][x] = (dp[y - 1][x] + dp[y][x - 1]) % MOD
    return sum(dp[y][x] for x in range(L, R + 1) for y in range(D, U + 1)) % MOD

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    mod = 998244353
    f = lambda p, q: p * q if (p % q) == 0 else None
    result = 0
    for a0 in range(1, 1001):
        sequence = [1, a0]
        for i in range(n - 2):
            next_val = f(sequence[-1], sequence[-2])
            if next_val == a[i] and (sequence[-1] % next_val) == 0:
                sequence.append(next_val)
            else:
                break
        if gcd(sequence[0], sequence[-1]) == 1:
            score = 1
            for j in range(1, len(sequence)):
                score *= sequence[j]
                score %= mod
            result += score
            result %= mod
    return result

