            if i + x <= n and t[i:i+x] == '1' * x and t[i+x:i+x+y] == '0' * y:
                count_a += 1
                i += x + y
            elif i + y <= n and t[i:i+y] == '0' * y and t[i+y:i+y+x] == '1' * x:
                count_b += 1
