    dp[(0, '')] = 1
    white_count, black_count = 0, 0
    for i, color in enumerate(reversed(s), start=1):
        if color == 'W':
            white_count += 1
        else:
            black_count += 1
        for prev_white, prev_black in list(dp.keys()):
            if white_count - prev_white != black_count - prev_black:
                continue
            dp[(white_count, black_count)] = (dp[(white_count, black_count)] +
                                                   dp[prev_white, prev_black] *
                                                   (prev_white - prev_black)) % mod
    return dp[(white_count, black_count)]

