def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    def helper(terms):
        s = sum(terms)
        if s == k:
            yield from product(terms),
        for i, n in enumerate(terms):
            yield from helper(terms[:i] + terms[i+1:])

    subsequences = list(helper(nums))
    subsequences.sort(reverse=True, key=lambda s: prod(s) if prod(s) <= limit else -1)
    return next((prod(s) for s in subsequences if prod(s) <= limit), -1)

