def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    if n < 2 or m < 2:
        return 0
    elif n == 2:
        return m * (m - 1) % MOD
    elif n == 3:
        return m * (m - 1) * (m - 2) % MOD
    else:
        prev_prev = [0] * m
        prev = [0] * m
        prev[0], prev[1] = m - 1, (m - 1) * (m - 2) % MOD
        for i in range(2, n):
            prev[i % m] = (prev_prev[(i - 2) % m] * (m - 2) + prev[(i - 1) % m] * (m - 1)) % MOD
            prev_prev[i % m] = prev[(i - 1) % m]
        return prev[n - 1 % m]

