def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    if C % 2 == 0 or D % 2 == 0:
        return 0
    else:
        width = C - A + 1
        height = D - B + 1
        if A % 2 == 0:
            black_rows = height // 2
        else:
            black_rows = (height + 1) // 2
        if B % 2 == 0:
            black_cols = width // 2
        else:
            black_cols = (width + 1) // 2
        return black_rows * 2 * black_cols * 2

def kth_smallest_amount(coins: List[int], k: int) -> int:
    def backtrack(coins, target, memo):
        if target in memo:
            return memo[target]
        if target == 0:
            return float('inf')
        if target < 0:
            return float('inf')
        memo[target] = float('inf')
        for coin in coins:
            memo[target] = min(memo[target], backtrack(coins, target - coin, memo) + coin)
        return memo[target]
    memo = {}
    return backtrack(coins, k - 1, memo)

