def count_power_representations(n: int) -> int:
    power_counts = [0] * (isqrt(n) * 2 + 1)
    for a in range(2, isqrt(n) + 1):
        base = a * a
        while base <= n:
            power_counts[base] += 1
            base *= a
    count = 0
    for i in range(5, isqrt(n) + 1):
        if n % i == 0:
            b1, b2 = n // i, i
            count += power_counts[b1] + power_counts[b2] - 1
    return count + isqrt(n)

