def count_good_sequences(N, M): import math, sympy
    MOD = 998244353
    factors = [1] * (N + 1)
    prime_factors = {}
    divisors = []
    for i in range(2, int(math.sqrt(N)) + 1):
        if factors[i] == 1:
            for j in range(i * i, N + 1, i):
                factors[j] += i
            prime_factors[i] = []
        for factor in prime_factors.get(i, []):
