def count_special_permutations(A: int, B: int, M: int) -> int:
    from math import comb, factorial

    def can_form_subseq(arr, lis, lds):
        lis_seq, lds_seq = [], []
        lis_len, lds_len = 0, 0
        for num in arr:
            if lis_seq and lis_seq[-1] > num:
                lis_seq.append(num)
                lis_len += 1
            elif lis_len < lis:
                lis_seq.append(num)
                lis_len += 1
            else:
                lis_seq.append(float('inf'))

            if lds_seq and lds_seq[-1] < num:
                lds_seq.append(num)
                lds_len += 1
            elif lds_len < lds:
                lds_seq.append(num)
                lds_len += 1
            else:
                lds_seq.append(float('inf'))

        return max(lis_len, lds_len) == max(lis, lds)

    def apply_increment(arr, increment):
        arr += increment
        return sorted(arr)

    def count_permutations(A, B, M, arr):
        lis_len, lds_len = A, B
        if not can_form_subseq(arr, lis_len, lds_len):
            return 0

        lis_start, lds_start = 1, 1
        for num in arr:
            if num < lis_start:
                lis_start = num + 1
            if num > lds_start:
                lds_start = num + 1

        lis_count = comb(arr.count(lis_start), lis_len)
        lds_count = comb(arr.count(lds_start), lds_len)

        total_count = lis_count * lds_count % M
        for num in arr:
            arr_copy = arr.copy()
            increment = num + 0.5
            if can_form_subseq(apply_increment(arr_copy, increment), lis_len, lds_len):
                total_count += count_permutations(A, B, M, arr_copy)
        return total_count % M

    return count_permutations(A, B, M, list(range(1, A*B - 1)))

