def find_largest_400_number(a: int) -> int:
    def is_400_number(n: int) -> bool:
        factors = set()
        while n % 2 == 0:
            factors.add(2)
            n //= 2
        p = 3
        while p * p <= n:
            while n % p == 0:
                factors.add(p)
                n //= p
            p += 2
        if n > 1:
            factors.add(n)
        return len(factors) == 2 and all(factor % 2 != 0 for factor in factors)

    result = 0
    for num in range(min(a, 10**6), 0, -1):
        if is_400_number(num):
            result = num
            break
    return result

