def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    def count_changes(i: int, j: int) -> int:
        return sum(c1 != c2 for c1, c2 in zip(s[i:j], s[i:j][::-1]))

    if len(s) <= 1:
        return 0

    dp = [[0] * len(s) for _ in range(k + 1)]

    for i in range(len(s)):
        dp[1][i] = count_changes(0, i + 1)

    for i in range(2, k + 1):
        for j in range(i, len(s)):
            dp[i][j] = min((dp[i][k] + count_changes(k, j + 1)) for k in range(i - 1, j))

    return dp[k][-1]

