def max_partitions_with_one_change(s: str, k: int) -> int:
    from collections import defaultdict
    from itertools import groupby

    def partitions(s, k):
        partitions = []
        poly_count = defaultdict(int)
        start = 0

        for char, group in groupby(s):
            if len(list(group)) > k:
                new_partition = s[start:start+len(list(group))]
                partitions.append(new_partition)
                start += len(list(group))
            else:
                poly_count[char] += len(list(group))

        if len(list(group)) > 0:
            partitions.append(s[start:])
        return partitions

    original_partitions = partitions(s, k)
    max_partitions = len(original_partitions)

    for i in range(len(s)):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            s_copy = s[:i] + c + s[i+1:]
            new_partitions = partitions(s_copy, k)
            if len(new_partitions) > max_partitions:
                max_partitions = len(new_partitions)

    return max_partitions

