def min_cost_to_achieve_goal(n: int, k: int, p: int, plans: List[Tuple[int, List[int]]]) -> int:
    plans.sort(key=lambda x: x[0])
    queue = deque()
    queue.append((0, 0, [0] * k))
    visited = set()
    min_cost = float('inf')

    while queue:
        cost, index, parameters = queue.popleft()
        if all(val >= p for val in parameters):
            min_cost = min(min_cost, cost)
        if index == len(plans):
            continue
        for j in range(n):
            if (index, j) in visited:
                continue
            visited.add((index, j))
            queue.append((cost + plans[j][0], j + 1, [val + plans[j][1][i] for i, val in enumerate(parameters)]))

    return -1 if min_cost == float('inf') else min_cost

def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    import numpy as np

    def is_equal(grid1: np.ndarray, grid2: np.ndarray) -> bool:
        return np.array_equal(grid1, grid2)

    def swap_rows(grid: np.ndarray, i: int, j: int) -> np.ndarray:
        grid[[i, j]] = grid[[j, i]]
        return grid

    def swap_cols(grid: np.ndarray, i: int, j: int) -> np.ndarray:
        grid[:, [i, j]] = grid[:, [j, i]]
        return grid

    def min_operations(grid_a: np.ndarray, grid_b: np.ndarray) -> int:
        visited = np.full((H, W), False)
        queue = [(grid_a.copy(), 0)]
        queue.sort(key=lambda tup: tup[1])
        seen = {tuple(grid_a.flatten()): 0}

        while queue:
            curr_grid, operations = queue.pop(0)
            if is_equal(curr_grid, grid_b):
                return operations
            if operations >= seen.get(tuple(curr_grid.flatten()), H * W):
                continue
            for i in range(H):
                for j in range(W):
                    if not visited[i, j]:
                        visited[i, j] = True
                        for di, dj in [(0, 1), (1, 0)]:
                            new_grid = swap_cols(curr_grid, j, j + di)
                            new_grid = swap_rows(new_grid, i, i + dj)
                            if tuple(new_grid.flatten()) not in seen:
                                seen[tuple(new_grid.flatten())] = operations + 1
                                queue.append((new_grid, operations + 1))

    grid_a = np.array(A)
    grid_b = np.array(B)

    if grid_a.shape != grid_b.shape:
        return None
    return min_operations(grid_a, grid_b) if min_operations(grid_a, grid_b) < H * W else None

