def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    directions = defaultdict(list)
    for u, v, w in edges:
        directions[u].append((v, w))

    pq = [(0, 0, 0)]  # (weight, visited, mask)
    visited = [False] * n
    mask = 1 << 0  # 0b0000000000000000000000000000001
    min_weight = float('inf')  # Initialize min_weight to positive infinity

    while pq:
        weight, visited_count, mask = heappop(pq)
        if visited_count == n - 1 and mask == (1 << n) - 1:
            if weight < min_weight:
                min_weight = weight
            continue
        if visited_count > n - 1 or mask == (1 << n) - 1:
            break
        next_vertex = None
        for v, w in directions[visited[-1]]:
            if not visited[v]:
                visited[v] = True
                heappush(pq, (weight + w, visited_count + 1, mask | (1 << v)))
                next_vertex = v
        if next_vertex is None:
            break
        visited[-1] = True
        mask |= (1 << next_vertex)
    return min_weight if min_weight != float('inf') else None

def divide_into_good_sequences(L: int, R: int) -> List[Tuple[int, int]]:
    sequences = []
    current_start = L
    while current_start < R:
        power = 1
        while (power * 2) <= current_start:
            power *= 2
        if (power * 2) < R:
            current_start = (power * 2)
        else:
            current_start += power
        sequences.append((current_start, min(R, current_start * 2)))
    return sequences

