def findProductQueries(queries: List[List[int]]) -> List[int]:
    def find_power_of_two(n: int) -> int:
        result = 1
        while result * 2 <= n:
            result *= 2
        return result

    def big_nums(n: int) -> List[int]:
        return [find_power_of_two(i) for i in range(n + 1)]

    def compute_query(from_i, to_i, mod_i, big_nums):
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        return product

    results = []
    max_index = max(max(q) for q in queries)
    big_nums_arr = big_nums(max_index)
    for from_i, to_i, mod_i in queries:
        results.append(compute_query(from_i, to_i, mod_i, big_nums_arr))
    return results

