def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    dp = [[0] * n for _ in range(n + 1)]
    res = [0] * (n + 1)

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            diff = a[j] - a[i]
            idx = j
            for k in range(j + 1, n):
                if a[k] - a[j] != diff:
                    idx = k - 1
                dp[i][j] += idx - j + 1
                dp[i][j] %= MOD

    for i in range(n):
        for j in range(i + 1, n):
            res[j] += dp[i][j]
            res[j] %= MOD

    return res[1:]

