def min_ng_list_size(n: int, product_names: List[str]) -> int:
    # Create a graph where nodes are alphabet letters and edges connect letters shared by product names
    graph = defaultdict(set)
    for name in product_names:
        for i in range(len(name) - 1):
            graph[name[i]].add(name[i + 1])

    # Find connected components
    visited = set()
    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    cc_map = defaultdict(list)
    for letter in graph:
        if letter not in visited:
            dfs(letter)
            cc_map[len(visited)].append(letter)

