    def count_subsequences(seq: list[int], target: int) -> int:
        count = 0
        dp = [[0 for _ in range(target + 1)] for _ in range(N + 1)]
        for i in range(N + 1):
            dp[i][0] = 1
        for i in range(1, N + 1):
            for j in range(1, target + 1):
                if seq[i - 1] == j:
                    dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
                else:
                    dp[i][j] = dp[i - 1][j]
        count = dp[N][target]
        return count % MOD

    def count_sequences_with_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
        count = 0
