MOD = 10**9 + 7

def count_subsequence_pairs(nums: List[int]) -> int:
    @lru_cache(None)
    def dfs(i, bitmask):
        if i == len(nums):
            return 1 if bin(bitmask).count('1') > 1 else 0
        include = dfs(i + 1, bitmask | (1 << nums[i]))
        exclude = dfs(i + 1, bitmask)
        return (include + exclude) % MOD

    ans = 0
    for i in range(1, 1 << len(nums)):
        for j in range(i):
            if gcd(int(''.join(str(b) for b in bin(i) if b == '1'), 2), int(''.join(str(b) for b in bin(j) if b == '1'), 2)) != 1:
                ans = (ans + dfs(0, i) * dfs(0, j)) % MOD
    return ans

def min_longest_substring(s: str, numOps: int) -> int:
    len_s = len(s)
    if numOps < 0 or numOps > len_s:
        return len_s
    if numOps == 0:
        return max(len(list(group)) for _, group ingroupby(s))
    dp = [0] * (numOps + 1)
    for i in range(1, len_s + 1):
        ones = s[i - 1] == '1'
        for j in range(numOps, -1, -1):
            flips = j - ones
            next_zero = dp[flips + 1]
            if flips > 0: next_zero = max(next_zero, dp[flips])
            total_zeros = ones + next_zero
            dp[j] = max(i - total_zeros, dp[j])
    return dp[numOps]

def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    if n <= 1:
        return False
    if n == 1 and not any(a <= i <= b for i in range(1, n + 1)): return False
    if n == 2:
        return a <= 2

    reachable = set(range(1, n + 1))
    for l, r in bad_intervals:
        reachable -= set(range(l, r + 1))

    while len(reachable) > 1:
        new_reachable = set()
        for x in reachable:
            for i in range(a, b + 1):
                y = x + i
                if y <= n and y in reachable:
                    new_reachable.add(y)
        reachable = new_reachable

    return len(reachable) > 0

