def max_shortest_distance(n, m, k, edges):
    from collections import deque

    # Create adjacency list for the graph
    adj_list = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj_list[u].append(v)

    # BFS to find the shortest path without edges of weight 1
    distances = [float('inf')] * (n + 1)
    distances[1] = 0
    queue = deque([1])
    while queue:
        current = queue.popleft()
        for neighbor in adj_list[current]:
            if (current, neighbor) not in edges:
                distances[neighbor] = min(distances[neighbor], distances[current] + 1)
                queue.append(neighbor)

    # Find the farthest reachable vertex
    farthest = max(distances[2:])

    # If the destination is not reachable, return 0
    if farthest == float('inf'):
        return 0

    # Create a priority queue to select k edges to set weight 1
    import heapq
    edge_heap = sorted((distances[v] for v in adj_list[u]) for u in range(1, n + 1))
    while k and edge_heap:
        current_min = edge_heap.pop()
        # If the current minimum distance is greater than the farthest reachable vertex, we can't improve it
        if current_min > farthest:
            break
        # Find the shortest path with at least one of the selected edges of weight 1
        distances_copy = distances.copy()
        for u in range(1, n + 1):
            if distances_copy[u] == current_min:
                for neighbor in adj_list[u]:
                    if (u, neighbor) not in edges:
                        distances_copy[neighbor] = min(distances_copy[neighbor], distances_copy[u] + 1)
        # Update the farthest reachable vertex if possible
        farthest = max(max(distances_copy[2:]) - 1, farthest)
        k -= 1

    return farthest

