import math

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    mod = 998244353
    factorial = [1] * (max(n, 1000) + 1)
    inverse_factorial = [1] * (max(n, 1000) + 1)
    for i in range(2, len(factorial)):
        factorial[i] = (factorial[i-1] * i) % mod
        inverse_factorial[i] = pow(factorial[i], mod-2, mod)

    def check_gcd(seq):
        return math.gcd.reduce(seq) == 1

    def score(seq):
        return math.prod(seq) % mod

    good_sequences = set()
    generate(0, 1, [], a, good_sequences)

    sum_scores = 0
    for seq in good_sequences:
        sum_scores = (sum_scores + score(seq)) % mod

    return sum_scores


