def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353
    fac = [1] * (n + 1)
    ifac = [1] * (n + 1)
    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        fac[i] = (fac[i - 1] * i) % MOD
        inv[i] = (MOD - MOD // i) * inv[MOD % i] % MOD
        ifac[i] = (ifac[i - 1] * inv[i]) % MOD

    def C(n, k):
        if k > n or k < 0: return 0
        return (fac[n] * ifac[k] % MOD) * ifac[n - k] % MOD

    def count_ways(n, ones, zeros):
        ways = 0
        for i in range(1, n + 1):
            if i % 2 == 1:
                ways = (ways + C(ones, ones - (n - i) // 2) * C(zeros, zeros - (n - i) // 2)) % MOD
            else:
                ways = (ways + C(ones, ones - (n - i) // 2) * C(zeros, zeros - (n - i) // 2) * (ones - zeros + 1)) % MOD
        return ways

    ones = s.count('1')
    zeros = n - ones
    return count_ways(n, ones, zeros)

def min_cost_to_sort(n, permutation):
    sorted_permutation = sorted(permutation)
    total_cost = 0
    for i in range(n):
        correct_position = sorted_permutation.index(permutation[i])
        if correct_position != i:
            for j in range(max(i, correct_position), i, -1):
                permutation[j], permutation[j - 1] = permutation[j - 1], permutation[j]
                total_cost += j
    return total_cost

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    MOD = 998244353
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1
    for len_ in range(2, n + 1):
        for i in range(n - len_ + 1):
            j = i + len_ - 1
            if s[i] == ')':
                dp[i][j] = dp[i + 1][j]
            else:
                dp[i][j] = (dp[i][j] + dp[i + 1][j]) % MOD
            if s[j] == '(': 
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
    return dp[0][n - 1]

