def dfs(vertex, parent, a, tree, result, visited):
    visited[vertex] = True
    for child, weight in tree[vertex]:
        if not visited[child]:
            dist = dist_and_check(child, parent, a[child], weight, a)
            if dist <= a[child]:
                result[child] += 1 + result[vertex]
            dfs(child, vertex, a, tree, result, visited)

def dist_and_check(vertex, parent, limit, weight, a):
    return weight + sum(a[c] for c in tree[vertex] if c != parent) + (a[parent] - weight if parent != -1 else 0)

